import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = string.parseFloat("1.5")
    match a {
        Some(w) => { io.println("got ${w}") }
        None => { io.println("a-none") }
    }
    let b = string.parseFloat("1.500")
    match b {
        Some(w) => { io.println("trim ${w}") }
        None => { io.println("b-none") }
    }
    let c = string.parseFloat("1.5e2")
    match c {
        Some(w) => { io.println("exp ${w}") }
        None => { io.println("c-none") }
    }
    let d = string.parseFloat("1.0e999")
    match d {
        Some(w) => { io.println("d-bad") }
        None => { io.println("d-none") }
    }
    return Ok(())
}
